        q("integration_setup", "남은 준비 작업과 담당자는 누구인가요?", "textarea", [], "운영 준비가 끝나지 않은 외부 연결의 계정·주소·시험·운영 설정·승인과 담당자만 적어요. 외부 제공자가 없다는 답변과 앞선 연결 선택이 다르면 두 답변을 먼저 맞춰요. 실제 키·토큰은 적지 않아요.", {"when":{"all":[{"not":{"id":"integration_readiness","value":"운영 설정·승인까지 준비"}},{"any":[{"not":{"id":"integration_readiness","value":"외부 제공자 없이 구현"}},{"any":[{"id":"external_api_usage","value":"외부 API 호출"},{"id":"features","includes":"외부 서비스 연동"},{"id":"features","includes":"결제·구독"},{"id":"backend_mode","value":"BaaS·관리형 백엔드"},{"id":"auth_implementation","value":"외부 인증 서비스"},{"id":"file_storage","in":["S3 계열 오브젝트 스토리지","관리형 백엔드 스토리지"]},{"id":"login_methods","in":["Google","GitHub","카카오","네이버","Apple","기업 SSO"]},{"id":"ai_provider","in":["OpenAI API","Anthropic Claude API","Google Gemini API"]},{"id":"map_provider","in":["카카오 지도","네이버 클라우드 Maps","Google Maps Platform"]},{"id":"notification_channels","in":["웹 푸시","모바일 푸시","SMS","카카오 알림톡"]},{"id":"email_provider","in":["전문 이메일 발송 서비스","인증 서비스의 기본 이메일 발송"]}]}]}]}})
